/**
 * GSAP REVEAL ENGINE v2.0
 * Fitur: Scrub, Reverse, Universal Target, 3D Transforms, & Advanced Masking
 */

gsap.registerPlugin(ScrollTrigger);

/* =========================
   HELPER & RESOLVER
========================= */
const get = (el, key, def) => {
    const val = el.dataset[key];
    if (val === undefined) return def;
    if (val === "true") return true;
    if (val === "false") return false;
    if (!isNaN(val)) return parseFloat(val);
    return val;
};

const resolveTarget = (el) => {
    const t = el.dataset.target;
    if (!t) return el.querySelector("img") || el;
    if (t === "self") return el;
    if (t === "parent") return el.parentElement;
    return el.querySelector(t) || el;
};

const resolveTrigger = (el) => {
    const t = el.dataset.trigger;
    if (!t || t === "false") return el;
    if (t === "parent") return el.parentElement;
    return document.querySelector(t) || el;
};

/* =========================
   CORE ANIMATION ENGINE
========================= */
const apply = (el, from, to, customSettings = {}) => {
    const target = resolveTarget(el);
    const triggerEl = resolveTrigger(el);
    const scrub = get(el, "scrub", false);
    const reverse = get(el, "reverse", false);

    // Konfigurasi Tween
    const config = {
        duration: get(el, "duration", 1.2),
        delay: get(el, "delay", 0),
        ease: get(el, "ease", customSettings.ease || "power2.out"),
        ...to,
        // Pastikan opacity default ke 1 jika tidak ditentukan di 'to'
        opacity: to.opacity !== undefined ? to.opacity : 1 
    };

    // 1. Initial State (Set posisi awal sebelum animasi)
    gsap.set(target, { 
        ...from, 
        visibility: "visible",
        immediateRender: true 
    });

    // 2. Jika Mode SCRUB (Animasi mengikuti scroll)
    if (scrub) {
        return gsap.fromTo(target, from, {
            ...config,
            ease: "none", // Scrub harus linear agar smooth
            scrollTrigger: {
                trigger: triggerEl,
                start: get(el, "start", "top 90%"),
                end: get(el, "end", "bottom 20%"),
                scrub: scrub
            }
        });
    }

    // 3. Jika Mode NORMAL (Play once / Trigger by scroll)
    const tween = gsap.fromTo(target, from, { ...config, paused: true });

    ScrollTrigger.create({
        trigger: triggerEl,
        start: get(el, "start", "top 85%"),
        end: "bottom top",
        onEnter: () => tween.play(),
        onLeave: () => reverse ? tween.reverse() : null,
        onEnterBack: () => reverse ? tween.play() : null,
        onLeaveBack: () => reverse ? tween.reverse() : null,
        // Reset jika elemen keluar jauh dari viewport (opsional)
        onRefresh: (self) => {
            if (self.progress === 0) tween.pause(0);
        }
    });

    return tween;
};

/* =========================
   PRESETS LIBRARY
========================= */
const presets = {
    // --- MASKING (CLIP PATH) ---
    "mask-up": (el) => apply(el, { clipPath: "inset(100% 0% 0% 0%)" }, { clipPath: "inset(0% 0% 0% 0%)" }),
    "mask-down": (el) => apply(el, { clipPath: "inset(0% 0% 100% 0%)" }, { clipPath: "inset(0% 0% 0% 0%)" }),
    "mask-left": (el) => apply(el, { clipPath: "inset(0% 0% 0% 100%)" }, { clipPath: "inset(0% 0% 0% 0%)" }),
    "mask-right": (el) => apply(el, { clipPath: "inset(0% 100% 0% 0%)" }, { clipPath: "inset(0% 0% 0% 0%)" }),
    "iris-in": (el) => apply(el, { clipPath: "circle(0% at 50% 50%)" }, { clipPath: "circle(75% at 50% 50%)" }),
    "door-horizontal": (el) => apply(el, { clipPath: "inset(0% 50% 0% 50%)" }, { clipPath: "inset(0% 0% 0% 0%)" }),
    "door-vertical": (el) => apply(el, { clipPath: "inset(50% 0% 50% 0%)" }, { clipPath: "inset(0% 0% 0% 0%)" }),
    "reveal-diagonal": (el) => apply(el, { clipPath: "polygon(0 100%, 0 100%, 0 100%, 0 100%)" }, { clipPath: "polygon(0 0, 100% 0, 100% 100%, 0 100%)" }),

    // --- BASIC MOTION ---
    "fade-in": (el) => apply(el, { opacity: 0 }, { opacity: 1 }),
    "slide-up": (el) => apply(el, { y: 80, opacity: 0 }, { y: 0, opacity: 1 }),
    "slide-down": (el) => apply(el, { y: -80, opacity: 0 }, { y: 0, opacity: 1 }),
    "slide-left": (el) => apply(el, { x: 80, opacity: 0 }, { x: 0, opacity: 1 }),
    "slide-right": (el) => apply(el, { x: -80, opacity: 0 }, { x: 0, opacity: 1 }),

    // --- ZOOM & SCALE ---
    "zoom-in": (el) => apply(el, { scale: 1.5, opacity: 0 }, { scale: 1, opacity: 1 }),
    "zoom-out": (el) => apply(el, { scale: 0.5, opacity: 0 }, { scale: 1, opacity: 1 }),
    "zoom-smooth": (el) => apply(el, { scale: 0, opacity: 0 }, { scale: 1, opacity: 1 }, { ease: "expo.out" }),

    // --- 3D TRANSFORMS (Membutuhkan Perspective pada parent CSS) ---
    "flip-x": (el) => apply(el, { rotateX: 90, opacity: 0, transformOrigin: "top" }, { rotateX: 0, opacity: 1 }),
    "flip-y": (el) => apply(el, { rotateY: -90, opacity: 0, transformOrigin: "left" }, { rotateY: 0, opacity: 1 }),
    "unfold": (el) => apply(el, { rotateX: -45, scale: 0.8, opacity: 0 }, { rotateX: 0, scale: 1, opacity: 1 }),
    "swing-in": (el) => apply(el, { rotateY: 25, x: 50, opacity: 0 }, { rotateY: 0, x: 0, opacity: 1 }),

    // --- ARTISTIC ---
    "blur-reveal": (el) => apply(el, { filter: "blur(20px)", opacity: 0, scale: 1.1 }, { filter: "blur(0px)", opacity: 1, scale: 1 }),
    "sharp-in": (el) => apply(el, { filter: "contrast(3) brightness(0)", opacity: 0 }, { filter: "contrast(1) brightness(1)", opacity: 1 }),
    "bounce-in": (el) => apply(el, { scale: 0.3, opacity: 0 }, { scale: 1, opacity: 1 }, { ease: "back.out(1.7)" }),
    "skew-in": (el) => apply(el, { skewX: 30, opacity: 0, x: 50 }, { skewX: 0, opacity: 1, x: 0 }),
    "pop-in": (el) => apply(el, { scale: 0, opacity: 0 }, { scale: 1, opacity: 1 }, { ease: "back.out(2)" }),
    "glitch": (el) => apply(el, { x: -20, opacity: 0 }, { x: 0, opacity: 1 }, { ease: "steps(4)" })
};

/* =========================
   INITIALIZATION
========================= */
const initReveals = () => {
    document.querySelectorAll("[data-reveal]").forEach(el => {
        const type = el.dataset.reveal;
        if (presets[type]) {
            presets[type](el);
        } else {
            console.warn(`Reveal preset "${type}" tidak ditemukan.`);
        }
    });
};

// Jalankan setelah DOM siap
if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", initReveals);
} else {
    initReveals();
}